svg.script:
/**/
(function() {
  var currentStep = 1;
  var isPlaying = false;
  var timer = null;

  var stepData = {
    1: {
      name: "ESTREITO SUPERIOR (ENTRADA)",
      badge: "ENTRADA PELVINA",
      badgeClass: "badge-superior",
      badgeColor: "var(--a12p9b-superior)",
      diameter: "13,0 cm",
      type: "Transiverso Maior",
      landmark: "Linha Terminal / Promontório à Sínfise Púbica",
      dynamics: "A cabeça fetal ingressa na pelve orientada preferencialmente no diâmetro TRANSVERSO ou OBLÍQUO (13 cm), aproveitando o maior espaço disponível na entrada pelvina.",
      ringId: "a12p9b-ring-superior",
      headY: 175,
      headRot: 0,
      headScaleX: 1.0,
      headScaleY: 0.95
    },
    2: {
      name: "ESTREITO MÉDIO (GARGALO)",
      badge: "O MENOR DIÂMETRO (GARGALO)",
      badgeClass: "badge-gargalo",
      badgeColor: "var(--a12p9b-medio)",
      diameter: "10,5 cm",
      type: "Diâmetro Biespinhal (Espinhas)",
      landmark: "Espinhas Isquiáticas / Plano de Menor Espaço",
      dynamics: "ACHADO CRÍTICO: O diâmetro biespinhal (10,5 cm) é o verdadeiro gargalo da pelve! Ao encontrar a resistência das espinhas isquiáticas, a cabeça fetal é forçada a realizar ROTAÇÃO INTERNA.",
      ringId: "a12p9b-ring-medio",
      headY: 315,
      headRot: 45,
      headScaleX: 0.88,
      headScaleY: 0.92
    },
    3: {
      name: "ESTREITO INFERIOR (SAÍDA)",
      badge: "SAÍDA PELVINA (2 TRIÂNGULOS)",
      badgeClass: "badge-inferior",
      badgeColor: "var(--a12p9b-inferior)",
      diameter: "11,0 cm",
      type: "Diâmetro Intertuberoso",
      landmark: "Arco Púbico, Tuberosidades e Cóccix",
      dynamics: "A saída bifurca-se em 2 triângulos (urogenital e anal). A cabeça fetal atravessa o triângulo anterior e DEFLETE (extensão) sob o arco subpúbico (11 cm).",
      ringId: "a12p9b-ring-inferior",
      headY: 475,
      headRot: 90,
      headScaleX: 0.95,
      headScaleY: 1.0
    }
  };

  function setStep(step) {
    if (step < 1) step = 3;
    if (step > 3) step = 1;
    currentStep = step;
    var d = stepData[step];

    // Update active tab buttons
    for (var i = 1; i <= 3; i++) {
      var btn = document.getElementById("a12p9b-btn-step-" + i);
      if (btn) {
        if (i === step) {
          btn.classList.add("is-active");
          btn.setAttribute("aria-selected", "true");
        } else {
          btn.classList.remove("is-active");
          btn.setAttribute("aria-selected", "false");
        }
      }
      var ring = document.getElementById(stepData[i].ringId);
      if (ring) {
        if (i === step) {
          ring.classList.add("is-highlighted");
        } else {
          ring.classList.remove("is-highlighted");
        }
      }
    }

    // Update Head Position & Rotation
    var headGroup = document.getElementById("a12p9b-fetal-head-group");
    if (headGroup) {
      headGroup.setAttribute("transform", "translate(300, " + d.headY + ") rotate(" + d.headRot + ") scale(" + d.headScaleX + ", " + d.headScaleY + ")");
    }

    // Update Head Status Text
    var headStatusText = document.getElementById("a12p9b-head-status-text");
    if (headStatusText) {
      headStatusText.textContent = "Passo " + step + "/3: " + (step === 1 ? "Orientação Transversa na Entrada (13,0 cm)" : (step === 2 ? "Compressão e Rotação Interna no Gargalo (10,5 cm)" : "Deflexão Anteroposterior na Saída (11,0 cm)"));
    }

    // Update Panel Data
    var titleEl = document.getElementById("a12p9b-card-title");
    if (titleEl) titleEl.textContent = d.name;

    var badgeEl = document.getElementById("a12p9b-card-badge");
    if (badgeEl) badgeEl.textContent = d.badge;

    var badgeBgEl = document.getElementById("a12p9b-card-badge-bg");
    if (badgeBgEl) badgeBgEl.setAttribute("fill", d.badgeColor);

    var valDiam = document.getElementById("a12p9b-val-diameter");
    if (valDiam) valDiam.textContent = d.diameter;

    var valType = document.getElementById("a12p9b-val-type");
    if (valType) valType.textContent = d.type;

    var valLandmark = document.getElementById("a12p9b-val-landmark");
    if (valLandmark) valLandmark.textContent = d.landmark;

    var valDynamics = document.getElementById("a12p9b-val-dynamics");
    if (valDynamics) valDynamics.textContent = d.dynamics;

    // Update Bar chart highlights
    for (var b = 1; b <= 3; b++) {
      var bar = document.getElementById("a12p9b-bar-" + b);
      if (bar) {
        if (b === step) {
          bar.classList.add("is-active");
        } else {
          bar.classList.remove("is-active");
        }
      }
    }

    // ARIA Live update
    var liveRegion = document.getElementById("a12p9b-aria-live");
    if (liveRegion) {
      liveRegion.textContent = "Plano " + step + ": " + d.name + ", diâmetro " + d.diameter + ". " + d.landmark + ". " + d.dynamics;
    }
  }

  // Bind Click Events
  for (var k = 1; k <= 3; k++) {
    (function(stepNum) {
      var btn = document.getElementById("a12p9b-btn-step-" + stepNum);
      if (btn) {
        btn.addEventListener("click", function() {
          stopAuto();
          setStep(stepNum);
        });
        btn.addEventListener("keydown", function(e) {
          if (e.key === "Enter" || e.key === " ") {
            e.preventDefault();
            stopAuto();
            setStep(stepNum);
          }
        });
      }
      var ring = document.getElementById(stepData[stepNum].ringId);
      if (ring) {
        ring.addEventListener("click", function() {
          stopAuto();
          setStep(stepNum);
        });
      }
    })(k);
  }

  var playBtn = document.getElementById("a12p9b-btn-play");
  function stopAuto() {
    if (isPlaying) {
      isPlaying = false;
      if (timer) clearInterval(timer);
      if (playBtn) {
        var playText = playBtn.querySelector("text");
        if (playText) playText.textContent = "▶ Simular Descida e Rotação Fetal";
      }
    }
  }

  if (playBtn) {
    playBtn.addEventListener("click", function() {
      if (isPlaying) {
        stopAuto();
      } else {
        isPlaying = true;
        var playText = playBtn.querySelector("text");
        if (playText) playText.textContent = "⏸ Pausar Descida";
        setStep((currentStep % 3) + 1);
        timer = setInterval(function() {
          setStep((currentStep % 3) + 1);
        }, 2500);
      }
    });
    playBtn.addEventListener("keydown", function(e) {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        playBtn.click();
      }
    });
  }

  // Keyboard navigation on Root SVG
  var rootSvg = document.getElementById("a12p9b-svg");
  if (rootSvg) {
    rootSvg.addEventListener("keydown", function(e) {
      if (e.key === "ArrowRight" || e.key === "ArrowDown") {
        e.preventDefault();
        stopAuto();
        setStep(currentStep + 1);
      } else if (e.key === "ArrowLeft" || e.key === "ArrowUp") {
        e.preventDefault();
        stopAuto();
        setStep(currentStep - 1);
      } else if (e.key === "1") {
        stopAuto(); setStep(1);
      } else if (e.key === "2") {
        stopAuto(); setStep(2);
      } else if (e.key === "3") {
        stopAuto(); setStep(3);
      }
    });
  }

  // Initialize Step 1
  setStep(1);
})();
/**/
